</code></pre> <pre><code>import base64
import requests
from pathlib import Path

API_URL = "https://api.regolo.ai/v1/chat/completions"
API_KEY = "YOUR-API-KEY"
MODEL = "deepseek-ocr"

IMAGE_PATH = Path("document.png")

with open(IMAGE_PATH, "rb") as f:
    image_bytes = f.read()

image_b64 = base64.b64encode(image_bytes).decode("utf-8")

payload = {
    "model": MODEL,
    "messages": [
        {
            "role": "user",
            "content": [
                {"type": "text", "text": "Convert the document to markdown."},
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/png;base64,{image_b64}",
                        "format": "image/png"
                    }
                }
            ]
        }
    ],
    "max_tokens": 4096,
    "skip_special_tokens": False
}

headers = {
    "Content-Type": "application/json",
    "Authorization": f"Bearer {API_KEY}"
}

response = requests.post(API_URL, headers=headers, json=payload)
result = response.json()
content = result["choices"][0]["message"]["content"]
print(content)
</code></pre> <pre><code>import base64
import requests

api_key = "YOUR_API_KEY"
model = "deepseek-ocr"

image_url = "https://example.com/document.png"
response = requests.get(image_url)
image_b64 = base64.b64encode(response.content).decode('utf-8')

url = "https://api.regolo.ai/v1/chat/completions"
payload = {
    "model": model,
    "messages": [
        {
            "role": "user",
            "content": [
                {
                    "type": "text",
                    "text": "Convert the document to markdown."
                },
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/png;base64,{image_b64}",
                        "format": "image/png"
                    }
                }
            ]
        }
    ],
    "max_tokens": 4096,
    "skip_special_tokens": False
}
headers = {
    "Content-Type": "application/json",
    "Authorization": f"Bearer {api_key}"
}

response = requests.post(url, json=payload, headers=headers)
result = response.json()
content = result["choices"][0]["message"]["content"]
print(content)
</code></pre> <p>Note on skip_special_tokens</p> <p>The <code>skip_special_tokens</code> parameter controls whether special tokens (like <code>&lt;|grounding|&gt;</code>) are included in the response: - <code>skip_special_tokens=False</code>: Keeps special tokens (default). Use when you need document structure info. - <code>skip_special_tokens=True</code>: Removes special tokens. Use for clean text output only.</p>
